#!/usr/bin/env node
import { mkdir, rm, writeFile, appendFile, cp, readFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { tmpdir } from 'node:os';
import { mkdtemp } from 'node:fs/promises';
import { createApp } from '../dist/src/app.js';
import { RecordedStructuredLLM } from '../dist/src/infrastructure/llm/recorded-structured-llm.js';
import { newId, nowIso } from '../dist/src/shared/utils.js';

const PROJECT_ROOT = resolve(new URL('..', import.meta.url).pathname);
const OUT = resolve(process.env.TRACE_OUT || join(PROJECT_ROOT, 'scenario-traces'));
const MODEL = 'GPT-5.6 Sol';
const PROVENANCE = 'Generated by GPT-5.6 Sol in the 2026-09-10 implementation/trace session; recorded for deterministic replay, not used by production runtime.';

const backendResume = `# Candidate\n\nBackend engineer using Java, MySQL and Redis.\n\n## Project\nUsed Redis cache-aside in an e-commerce service. Improved API latency by 40%.`;
const backendJd = `Backend Engineer. Strong Java concurrency required. Experience with Redis caching and consistency required. Strong relational database transaction fundamentals preferred.`;
const aiResume = `# Candidate\n\nBackend engineer who built an LLM tool-calling prototype with local memory and structured tool schemas. I have not yet built a formal agent evaluation suite.`;

function entry(name, output) { return { name, model: MODEL, provenance: PROVENANCE, capturedAt: nowIso(), output }; }

